Definition roomtr (A : AS) (vm : VmMaps) (A' : AS) (vm' : VmMaps) (K B : Z) : Prop :=
  forall k b, aroom A vm k b -> K <= k -> B <= b -> aroom A' vm' (k - K) (b - B).

