      live A' (Z_to_bv 64 0) = None -> (forall q, q <> Z_to_bv 64 0 -> live A' q = live A q) ->
      POSTM C A s m m' ->
      roomtr A (m_vmmaps md) A' vm' 0 0 ->
      realizes al_segs (mkCfg (mkst regs' ret m' al_rom) (with_vmmaps vm' md)) S) ->
